## 3. Hooking the library into MapLibre iOS

MapLibre iOS expects a **`TileDataSource`** (or, for raster tiles, a `RasterTileSource`) that can return the raw tile bytes for a given `(z, x, y)` coordinate.  
We’ll create a tiny wrapper that asks the PMTiles archive for the tile data and hands it back to the map.

### 3.1. Minimal `PMTilesDataSource`

```swift
import Foundation
import MapLibre
import PMTiles // <-- the Swift package

/// A TileDataSource that reads tiles from a remote or local PMTiles archive.
final class PMTilesDataSource: TileDataSource {
    private let archive: PMTilesArchive
    private let cache = NSCache<NSString, NSData>()   // optional in‑memory cache

    /// Initialise with a *remote* URL (e.g. Cloudflare R2) or a local file URL.
    init(url: URL) async throws {
        // The PMTilesArchive will lazily issue HTTP Range requests when needed.
        self.archive = try await PMTilesArchive(url: url)
    }

    /// MapLibre calls this for every tile it wants to render.
    func data(for tileID: TileID) async throws -> Data {
        // PMTiles uses the XYZ scheme (z, x, y) – same as MapLibre.
        let z = tileID.z
        let x = tileID.x
        let y = tileID.y

        // Optional cache key – you can skip this if you rely on the archive's own caching.
        let cacheKey = "\(z)/\(x)/\(y)" as NSString
        if let cached = cache.object(forKey: cacheKey) {
            return cached as Data
        }

        // Ask the archive for the tile bytes.
        guard let tile = try await archive.getTile(z: z, x: x, y: y) else {
            // No tile at this location → return an empty Data (MapLibre will treat it as transparent)
            throw TileError.tileMissing
        }

        // Store in our simple cache.
        cache.setObject(tile as NSData, forKey: cacheKey)

        return tile
    }

    enum TileError: Error {
        case tileMissing
    }
}
```

**Key points**

* `PMTilesArchive(url:)` works with **any URL that supports HTTP Range** – Cloudflare R2 does out of the box.  
* The archive is **lazy**: it only fetches the byte ranges it needs, so you never download the whole 3 GB file.  
* You can add a small `NSCache` (or use `URLCache`) to keep recently‑used tiles in memory.  
* The `TileDataSource` protocol is **async/await**‑based (MapLibre iOS ≥ 6.0). If you’re on an older version you can adapt it to the older completion‑handler API.

### 3.2. Register the source with the style

```swift
import UIKit
import MapLibre

class MapViewController: UIViewController {
    private var mapView: MapView!

    override func viewDidLoad() {
        super.viewDidLoad()

        // 1️⃣ Initialise the MapLibre view.
        mapView = MapView(frame: view.bounds, mapInitOptions: .init(styleURI: .streets))
        mapView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        view.addSubview(mapView)

        // 2️⃣ Create the PMTiles data source (remote URL on R2).
        Task {
            do {
                let pmtilesURL = URL(string: "https://my-bucket.r2.cloudflarestorage.com/basemap.pmtiles")!
                let pmtilesSource = try await PMTilesDataSource(url: pmtilesURL)

                // 3️⃣ Build a raster source that uses our data source.
                //    If you have vector tiles, use `VectorSource` instead.
                let rasterSource = RasterSource(
                    id: "pmtiles-basemap",
                    tileDataSource: pmtilesSource,
                    tileSize: 256,               // match the tile size in the archive
                    attribution: "© My Data Provider"
                )

                // 4️⃣ Add the source + a raster layer to the style.
                try await mapView.mapboxMap.style.addSource(rasterSource)

                var rasterLayer = RasterLayer(id: "pmtiles-basemap-layer", source: rasterSource.id)
                rasterLayer.rasterOpacity = .constant(1.0)

                try await mapView.mapboxMap.style.addLayer(rasterLayer)
            } catch {
                print("❌ Failed to set up PMTiles source: \(error)")
            }
        }
    }
}
```

*If you are using **vector tiles** (e.g. MapLibre‑compatible vector style), replace `RasterSource` with `VectorSource` and add the appropriate `LineLayer`, `FillLayer`, etc., referencing the source ID.*

### 3.3. Optional: Register a global `pmtiles://` scheme

If you prefer to keep the same URL syntax you use on the web (`pmtiles://https://…/mytiles.pmtiles`), you can implement a **custom `URLProtocol`** that intercepts that scheme and forwards the request to `PMTilesArchive`. The code below shows a lightweight version:

```swift
final class PMTilesURLProtocol: URLProtocol {
    private static let archiveCache = NSCache<NSURL, PMTilesArchive>()

    override class func canInit(with request: URLRequest) -> Bool {
        // Only handle our custom scheme.
        return request.url?.scheme == "pmtiles"
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    private var task: Task<Void, Never>?

    override func startLoading() {
        guard let pmtilesURL = request.url?.absoluteString
                .replacingOccurrences(of: "pmtiles://", with: "") // strip the custom prefix
                .addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
              let remoteURL = URL(string: pmtilesURL) else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }

        task = Task {
            do {
                // Re‑use archives for the same remote URL.
                let archive = try await Self.archiveCache.object(forKey: remoteURL as NSURL) ??
                              PMTilesArchive(url: remoteURL)
                Self.archiveCache.setObject(archive, forKey: remoteURL as NSURL)

                // Parse XYZ from the request path: /{z}/{x}/{y}.pbf (or .png, .jpg, …)
                let components = remoteURL.pathComponents.filter { $0 != "/" }
                guard components.count >= 3,
                      let z = Int(components[components.count - 3]),
                      let x = Int(components[components.count - 2]),
                      let yString = components.last,
                      let y = Int(yString.split(separator: ".").first ?? "") else {
                    throw URLError(.badURL)
                }

                guard let tileData = try await archive.getTile(z: z, x: x, y: y) else {
                    // 404‑style response
                    let response = HTTPURLResponse(url: request.url!,
                                                   statusCode: 204,
                                                   httpVersion: nil,
                                                   headerFields: nil)!
                    client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
                    client?.urlProtocolDidFinishLoading(self)
                    return
                }

                // Build a fake HTTP response so MapLibre can treat it as a normal tile request.
                let mime = archive.mimeType ?? "application/octet-stream"
                let response = HTTPURLResponse(url: request.url!,
                                               statusCode: 200,
                                               httpVersion: nil,
                                               headerFields: ["Content-Type": mime])!
                client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
                client?.urlProtocol(self, didLoad: tileData)
                client?.urlProtocolDidFinishLoading(self)
            } catch {
                client?.urlProtocol(self, didFailWithError: error)
            }
        }
    }

    override func stopLoading() {
        task?.cancel()
    }
}

// Register once, e.g. in AppDelegate:
URLProtocol.registerClass(PMTilesURLProtocol.self)
```

Now you can write the source

## TL;DR  

* **MapLibre iOS does not ship a built‑in `pmtiles://` handler**, but you can add one yourself with only a few lines of code.  
* The easiest path is to **drop the official PMTiles Swift package into your Xcode project** and write a tiny `URLProtocol` (or a custom `TileSource`) that uses the library to fetch tiles from the remote `.pmtiles` file via HTTP Range requests.  
* You **don’t have to run a tile server** and you **don’t need to convert the 3 GB archive to MBTiles** (which would waste storage and add a costly conversion step).  

Below is a step‑by‑step guide, plus a minimal working example that you can copy‑paste into a new iOS project.

---

## 1. Why the “pmtiles://” trick works on the web

The `pmtiles` NPM package registers a **custom URL scheme** (`pmtiles://`) with the browser’s fetch stack. When MapLibre (or any other map library) asks for a tile URL like  

```
pmtiles://https://my-bucket.r2.cloudflarestorage.com/world.pmtiles
```

the package intercepts the request, opens the remote `.pmtiles` file, issues **HTTP Range** requests to pull just the byte‑range that contains the requested tile, and returns the raw tile data. No server‑side conversion, no full download.

The same idea can be reproduced on iOS – you just need a Swift (or C++) implementation of the PMTiles spec and a way to plug it into the URL‑loading system that MapLibre uses.

---

## 2. What you have on iOS today

| Feature | Status in MapLibre iOS |
|---------|------------------------|
| **MBTiles** (local SQLite) | ✅ Supported via `TileStore` / offline packs |
| **XYZ/WMTS HTTP** | ✅ Supported out of the box |
| **Custom URL schemes** | ✅ Supported via `URLProtocol` registration (or a custom `TileSource`) |
| **PMTiles** | ❌ No built‑in support, but **easy to add** |

So you have two viable routes:

1. **Write a custom source** that talks to the PMTiles archive (recommended).  
2. **Convert to MBTiles** and load it as an offline pack (possible, but you’ll have to ship a 3 GB SQLite file on the device – not ideal).  

Running a separate tile server is the third option, but it adds latency, cost, and a moving‑target for authentication. The native approach is usually the cleanest.

---

## 3. The Swift PMTiles library

The official repository ships a **pure‑Swift implementation** that works on iOS, macOS, and even Linux:

```
https://github.com/Protomaps/PMTiles/tree/main/swift
```

You can add it to your project in three ways:

| Method | How |
|--------|-----|
| **Swift Package Manager** (recommended) | `File → Swift Packages → Add Package Dependency…` → paste `https://github.com/Protomaps/PMTiles.git` and select the `PMTiles` product. |
| **CocoaPods** | `pod 'PMTiles'` (the pod is just a thin wrapper around the Swift package). |
| **Manual copy** | Drag the `PMTiles` folder into your Xcode project. |

The library gives you two main entry points:

* `PMTilesArchive` – open a local file or a remote URL (via HTTP Range).  
* `PMTilesReader` – low‑level API to read a tile by `z/x/y`.

All the heavy lifting (parsing the header, locating the tile index, issuing range requests) is already done for you.

---

## 4. Two ways to hook it into MapLibre

### 4.1. Register a custom `URLProtocol`

MapLibre iOS ultimately asks `URLSession` for the tile data. If you register a `URLProtocol` that claims the `pmtiles` scheme, you can intercept the request, hand it to `PMTilesReader`, and return the bytes.

**Pros**

* Works with any source that uses a URL template (e.g., `VectorTileSource(url: "pmtiles://…")`).  
* No need to subclass MapLibre classes.

**Cons**

* Slightly more boilerplate if you also need to support authentication headers, caching, etc.

#### Implementation

```swift
import Foundation
import PMTiles

/// A URLProtocol that knows how to serve tiles from a remote .pmtiles file.
final class PMTilesProtocol: URLProtocol {

    // MARK: - URLProtocol required overrides

    override class func canInit(with request: URLRequest) -> Bool {
        // Only handle our custom scheme.
        return request.url?.scheme?.lowercased() == "pmtiles"
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest {
        return request
    }

    // MARK: - Instance state

    private var task: URLSessionDataTask?
    private static var archiveCache = NSCache<NSURL, PMTilesArchive>()

    // MARK: - Start / Stop loading

    override func startLoading() {
        guard let url = request.url else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }

        // The URL after the scheme is the *real* HTTP URL of the .pmtiles file.
        // Example: pmtiles://https://example.com/world.pmtiles
        let httpURLString = url.absoluteString
            .replacingOccurrences(of: "pmtiles://", with: "")
        guard let httpURL = URL(string: httpURLString) else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }

        // Re‑use an archive instance per remote file (cached in memory).
        let archive: PMTilesArchive
        if let cached = Self.archiveCache.object(forKey: httpURL as NSURL) {
            archive = cached
        } else {
            // The library will lazily issue HTTP Range requests as needed.
            archive = PMTilesArchive(url: httpURL)
            Self.archiveCache.setObject(archive, forKey: httpURL as NSURL)
        }

        // Parse the tile coordinates from the request path.
        // MapLibre asks for URLs like: pmtiles://https://…/z/x/y.{pbf|png}
        // We'll strip the leading slash and split.
        let path = url.path // "/z/x/y.pbf"
        let components = path.split(separator: "/")
        guard components.count >= 3,
              let z = UInt8(components[0]),
              let x = UInt64(components[1]),
              let yPart = components[2].split(separator: ".").first,
              let y = UInt64(yPart) else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }

        // Ask the archive for the tile data.
        archive.getTile(z: z, x: x, y: y) { result in
            switch result {
            case .success(let data):
                // Build a minimal HTTP response.
                let mime: String
                if url.pathExtension == "pbf" { mime = "application/x-protobuf" }
                else if url.pathExtension == "png" { mime = "image/png" }
                else { mime = "application/octet-stream" }

                let response = URLResponse(
                    url: url,
                    mimeType: mime,
                    expectedContentLength: data.count,
                    textEncodingName: nil)

                self.client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
                self.client?.urlProtocol(self, didLoad: data)
                self.client?.urlProtocolDidFinishLoading(self)

            case .failure(let err):
                self.client?.urlProtocol(self, didFailWithError: err)
            }
        }
    }

    override func stopLoading() {
        task?.cancel()
        task = nil
    }
}
```

**Register it once (e.g., in `AppDelegate` or before you create the map view):**

```swift
URLProtocol.registerClass(PMTilesProtocol.self)
```

Now you can create a normal `VectorTileSource`:

```swift
import MapLibre

let source = VectorTileSource(
    identifier: "world",
    tileURLTemplates: ["pmtiles://https://my-bucket.r2.cloudflarestorage.com/world.pmtiles/{z}/{x}/{y}.pbf"],
    tileSize: 512,
    attribution: "© My Data"
)

let style = Style(json: [
    "version": 8,
    "sources": [
        "world": source.json()
    ],
    "layers": [
        [
            "id": "world-fill",
            "type": "fill",
            "source": "world",
            "source-layer": "land",
            "paint": ["fill-color": "#e0e0e0"]
        ]
    ]
])

let mapView = MapView(frame: view.bounds, style: style)
view.addSubview(mapView)
```

That’s it – MapLibre will request tiles using the `pmtiles://` scheme, the protocol handler will fetch them from the remote archive, and the map will render them exactly as it does on the web.

---

### 4.2. Write a custom `TileSource` (alternative)

If you prefer to keep everything inside MapLibre’s own classes, you can subclass `TileSource` (or `VectorTileSource`) and override `loadTile(at:zoom:completion:)`. The body of that method would call the same `PMTilesArchive.getTile` API shown above.

**Skeleton:**

```swift
class PMTilesVectorSource: VectorTileSource {
    private let archive: PMTilesArchive

    init(id: String, pmtilesURL: URL) {
        self.archive = PMTilesArchive(url: pmtilesURL)
        super.init(identifier: id,
                   tileURLTemplates: [], // not used
                   tileSize: 512,
                   attribution: nil)
    }

    override func loadTile(at coordinate: TileCoordinate,
                           zoomLevel: UInt8,
                           completion: @escaping (Result<Data, Error>) -> Void) {
        archive.getTile(z: zoomLevel, x: UInt64(coordinate.x), y: UInt64(coordinate.y)) { result in
            completion(result)
        }
    }
}
```

Then add it to the style exactly like any other source. This approach avoids the global `URLProtocol` registration (useful if you have multiple archives with different authentication schemes) but requires a tiny bit more boilerplate.

---

## 5. What about authentication / signed URLs?

* **Cloudflare R2** supports **public buckets** (no auth) – the example above works out‑of‑the‑box.  
* If you need **signed URLs** (e.g., temporary tokens), you can generate them on the server side and embed the signed URL in the `pmtiles://` string. The `PMTilesArchive` will treat it as a normal HTTP URL and include the query string in its Range requests.  
* For **Bearer‑token** or **custom header** auth, you can subclass `PMTilesArchive` (or wrap it) and provide a custom `URLSessionConfiguration` with the needed headers. The library exposes an initializer that accepts a `URLSession` – just inject a session that adds the auth header to every request.

```swift

Below is a **complete, self‑contained TypeScript example** that

1. **creates an IndexedDB database** (`tile‑cache`) that stores vector‑tile blobs under the key `z/x/y`,
2. **exposes a custom `cache://` protocol** to MapLibre GL JS via `map.addProtocol`,
3. **shows how to pre‑populate the cache** (e.g. on first load or on‑the‑fly) and
4. **uses the protocol in a style URL** (`cache://tiles/{z}/{x}/{y}`).

> **Why a custom protocol?**  
> MapLibre GL JS lets you register a *protocol handler* (`map.addProtocol`) that receives the URL after the scheme (`cache:`) and must return a `Promise<ArrayBuffer | Response>`. By wiring that handler to IndexedDB you get a **pure‑in‑browser tile cache** that works even when the page is offline.

---

## 1️⃣  IndexedDB helper (tiny wrapper)

```ts
// src/idb.ts
export interface TileKey {
  z: number;
  x: number;
  y: number;
}

/**
 * Very small wrapper around IndexedDB that stores raw tile blobs.
 * The object store key is a string "z/x/y".
 */
export class TileCache {
  private static DB_NAME = "tile-cache";
  private static STORE_NAME = "tiles";
  private static DB_VERSION = 1;

  private db!: IDBDatabase;

  /** Open (or create) the DB – call once at startup */
  async open(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(TileCache.DB_NAME, TileCache.DB_VERSION);

      request.onupgradeneeded = () => {
        const db = request.result;
        // keyPath = "id" → we will store the key as a string "z/x/y"
        db.createObjectStore(TileCache.STORE_NAME, { keyPath: "id" });
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  /** Build the string key used in the object store */
  private static makeId({ z, x, y }: TileKey): string {
    return `${z}/${x}/${y}`;
  }

  /** Store a tile (ArrayBuffer) */
  async put(key: TileKey, data: ArrayBuffer): Promise<void> {
    const tx = this.db.transaction(TileCache.STORE_NAME, "readwrite");
    const store = tx.objectStore(TileCache.STORE_NAME);
    store.put({ id: TileCache.makeId(key), data });
    return tx.complete;
  }

  /** Retrieve a tile – resolves to undefined if not cached */
  async get(key: TileKey): Promise<ArrayBuffer | undefined> {
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readonly");
      const store = tx.objectStore(TileCache.STORE_NAME);
      const request = store.get(TileCache.makeId(key));

      request.onsuccess = () => {
        const result = request.result as { data: ArrayBuffer } | undefined;
        resolve(result?.data);
      };
      request.onerror = () => reject(request.error);
    });
  }

  /** Optional: delete a tile (e.g. for cache‑eviction) */
  async delete(key: TileKey): Promise<void> {
    const tx = this.db.transaction(TileCache.STORE_NAME, "readwrite");
    const store = tx.objectStore(TileCache.STORE_NAME);
    store.delete(TileCache.makeId(key));
    return tx.complete;
  }
}
```

> **Tip** – If you need a more feature‑rich wrapper (automatic versioning, TTL, etc.) you can drop‑in `idb` (https://github.com/jakearchibald/idb) and replace the above class with a few one‑liners.

---

## 2️⃣  Register the `cache://` protocol with MapLibre GL JS

```ts
// src/map.ts
import maplibregl, { Map, RequestParameters } from "maplibre-gl";
import { TileCache, TileKey } from "./idb";

/**
 * Register a custom protocol named "cache". MapLibre will call this
 * function for every URL that starts with "cache://".
 *
 * The handler receives:
 *   - params: { url: string, zoom: number, ... } (the full URL string)
 *   - abortCtrl: AbortController (useful for cancelling fetches)
 *
 * It must return a Promise that resolves to:
 *   - an ArrayBuffer (raw tile data) OR
 *   - a Response object (e.g. new Response(arrayBuffer, { headers }))
 *
 * If the tile is not in IndexedDB we fall back to a network request,
 * store the result, and then return it.
 */
export async function registerCacheProtocol(map: Map, cache: TileCache) {
  // Ensure the DB is ready before we start handling requests
  await cache.open();

  map.addProtocol("cache", async (params: RequestParameters, abortCtrl: AbortController) => {
    // --------------------------------------------------------------
    // 1️⃣  Parse the URL: cache://tiles/{z}/{x}/{y}
    // --------------------------------------------------------------
    // params.url is the full URL string, e.g. "cache://tiles/12/3456/7890"
    const url = new URL(params.url);
    // Remove leading slash from pathname (URL.pathname always starts with "/")
    const [, zStr, xStr, yStr] = url.pathname.split("/"); // ["", "tiles", "12", "3456", "7890"]
    const z = Number(zStr);
    const x = Number(xStr);
    const y = Number(yStr);

    if (Number.isNaN(z) || Number.isNaN(x) || Number.isNaN(y)) {
      throw new Error(`Invalid cache tile URL: ${params.url}`);
    }

    const key: TileKey = { z, x, y };

    // --------------------------------------------------------------
    // 2️⃣  Try to read from IndexedDB
    // --------------------------------------------------------------
    const cached = await cache.get(key);
    if (cached) {
      // Return raw ArrayBuffer – MapLibre will treat it as the tile payload
      return cached;
    }

    // --------------------------------------------------------------
    // 3️⃣  Not cached → fetch from the real source, store, then return
    // --------------------------------------------------------------
    // You can hard‑code the remote source or make it configurable.
    // Example remote source (replace with your own):
    const remoteUrl = `https://example.com/tiles/${z}/${x}/${y}.pbf`;

    const response = await fetch(remoteUrl, { signal: abortCtrl.signal });
    if (!response.ok) {
      // Propagate the HTTP error to MapLibre (it will show a missing‑tile placeholder)
      throw new Error(`Network error ${response.status} for ${remoteUrl}`);
    }

    const arrayBuffer = await response.arrayBuffer();

    // Store for next time (fire‑and‑forget – we don't block the tile render)
    cache.put(key, arrayBuffer).catch(console.error);

    // Return the freshly‑fetched data
    return arrayBuffer;
  });
}

/**
 * Example: create the map and use the custom protocol in the style.
 */
export async function initMap(containerId: string) {
  const map = new maplibregl.Map({
    container: containerId,
    style: {
      version: 8,
      sources: {
        // The source points to the custom scheme.
        "my-vector": {
          type: "vector",
          // Note the `{z}/{x}/{y}` placeholders – MapLibre will replace them.
          tiles: ["cache://tiles/{z}/{x}/{y}"],
          // Optional: set a maxzoom that matches your source
          maxzoom: 14,
        },
      },
      layers: [
        {
          id: "my-layer",
          type: "fill",
          source: "my-vector",
          "source-layer": "my_layer_name", // <-- change to your source‑layer
          paint: {
            "fill-color": "#88c0d0",
            "fill-opacity": 0.6,
          },
        },
      ],
    },
    center: [0, 0],
    zoom: 2,
  });

  // Register the protocol *after* the map instance exists
  const cache = new TileCache();
  await registerCacheProtocol(map, cache);

  // Optional: pre‑warm the cache (e.g. fetch tiles for the initial viewport)
  // See the helper function below if you want to do that.
  // await prefetchTilesForViewport(map, cache);

  return map;
}
```

### What the handler does, step‑by‑step

| Step | Action | Why |
|------|--------|-----|
| **Parse URL** | Extract `z/x/y` from `cache://tiles/{z}/{x}/{y}` | MapLibre passes the fully‑expanded URL (placeholders already replaced). |
| **Read from IndexedDB** | `cache.get(key)` | Fast, offline‑first. |
| **If found** | Return the `ArrayBuffer` directly. | No network request, zero latency. |
| **If missing** | `fetch(remoteUrl)` → `arrayBuffer()` → `cache.put(key, ...)` → return data. | Populate the cache on‑the‑fly, so the next request is served locally. |
| **Abort handling** | Pass `abortCtrl.signal` to `fetch`. | Allows MapLibre to cancel the request if the tile is no longer needed (e.g. fast pan). |

