## 3️⃣  (Optional) Pre‑fetch tiles for the initial viewport

If you want to **seed the cache** before the user sees the map (e.g. during a splash screen), you can compute the tile coordinates that intersect the current view and request them manually:

```ts
// src/prefetch.ts
import { Map } from "maplibre-gl";
import { TileCache, TileKey } from "./idb";

/**
 * Convert a latitude/longitude to a tile coordinate at a given zoom.
 */
function lngLatToTile(lng: number, lat: number, zoom: number): TileKey {
  const tileCount = 1 << zoom;
  const x = Math.floor(((lng + 180) / 360) * tileCount);
  const y = Math.floor(
    ((1 -
      Math.log(Math.tan((lat * Math.PI) / 180) + 1 / Math.cos((lat * Math.PI) / 180)) /
        Math.PI) /
      2) *
      tileCount
  );
  return { z: zoom, x, y };
}

/**
 * Get a list of tile keys that intersect the current map bounds at a given zoom.
 */
function tilesInBounds(map: Map, zoom: number): TileKey[] {
  const bounds = map.getBounds(); // LngLatBounds
  const nw = lngLatToTile(bounds.getWest(), bounds.getNorth(), zoom);
  const se = lngLatToTile(bounds.getEast(), bounds.getSouth(), zoom);

  const tiles: TileKey[] = [];
  for (let x = nw.x; x <= se.x; x++) {
    for (let y = nw.y; y <= se.y; y++) {
      tiles.push({ z: zoom, x, y });
    }
  }
  return tiles;
}

/**
 * Fetch & cache all tiles for the given zoom level.
 */
export async function prefetchTilesForViewport(map: Map, cache: TileCache, zoom = 12) {
  const tileKeys = tilesInBounds(map, zoom);
  const remoteBase = "https://example.com/tiles"; // same base you used in the protocol

  await Promise.all(
    tileKeys.map(async (key) => {
      // Skip if already cached
      if (await cache.get(key)) return;

      const url = `${remoteBase}/${key.z}/${key.x}/${key.y}.pbf`;
      try {
        const resp = await fetch(url);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.arrayBuffer();
        await cache.put(key, data);
      } catch (e) {
        console.warn(`Failed to prefetch ${url}:`, e);
      }
    })
  );
}
```

You can call `await prefetchTilesForViewport(map, cache, 12);` right after `registerCacheProtocol` if you want to warm the cache for the initial view.

