## 2️⃣  IndexedDB “Tile Cache” implementation

```ts
// src/cache/TileCache.ts
import { openDB, DBSchema, IDBPDatabase } from 'idb';

/**
 * The shape of our IndexedDB database.
 */
interface TileCacheDB extends DBSchema {
  /** Primary key = `${z}/${x}/${y}` */
  tiles: {
    key: string;
    value: Uint8Array; // raw .pbf bytes
  };
}

/**
 * Singleton wrapper around the IndexedDB instance.
 */
export class TileCache {
  private static _instance: TileCache;
  private db!: IDBPDatabase<TileCacheDB>;

  private constructor() {}

  /** Get the singleton */
  static async get(): Promise<TileCache> {
    if (!TileCache._instance) {
      TileCache._instance = new TileCache();
      await TileCache._instance._init();
    }
    return TileCache._instance;
  }

  /** Open (or create) the DB */
  private async _init() {
    this.db = await openDB<TileCacheDB>('maplibre-tile-cache', 1, {
      upgrade(db) {
        // `tiles` store holds raw PBF bytes keyed by "z/x/y"
        db.createObjectStore('tiles');
      },
    });
  }

  /** Store a tile (z/x/y) → Uint8Array */
  async put(z: number, x: number, y: number, data: Uint8Array): Promise<void> {
    const key = `${z}/${x}/${y}`;
    await this.db.put('tiles', data, key);
  }

  /** Retrieve a tile. Returns undefined if not cached. */
  async get(z: number, x: number, y: number): Promise<Uint8Array | undefined> {
    const key = `${z}/${x}/${y}`;
    return this.db.get('tiles', key);
  }

  /** Optional: delete a tile */
  async delete(z: number, x: number, y: number): Promise<void> {
    const key = `${z}/${x}/${y}`;
    await this.db.delete('tiles', key);
  }

  /** Optional: clear the whole cache */
  async clear(): Promise<void> {
    await this.db.clear('tiles');
  }
}
```

> **Why `Uint8Array`?**  
> MapLibre expects the tile data as an `ArrayBuffer` (or `Uint8Array`). Storing the raw bytes avoids any extra encoding/decoding steps.

---

## 3️⃣  The `cache://` protocol handler

MapLibre GL JS (and its fork Mapbox GL JS) expose a **protocol registration API**:

```ts
map.addProtocol(name: string, handler: (params, callback) => void);
```

The handler receives a `params` object that contains the URL **without** the scheme, e.g.

```
cache://tiles/12/3456/7890   →   params.url = "tiles/12/3456/7890"
```

We parse the URL, look the tile up in IndexedDB, and call the `callback` with the raw bytes.

```ts
// src/cache/cacheProtocol.ts
import { TileCache } from './TileCache';
import maplibregl, { RequestParameters, RequestCallback } from 'maplibre-gl';

/**
 * MapLibre protocol handler for `cache://`.
 *
 * It resolves URLs of the form:
 *   cache://tiles/{z}/{x}/{y}
 *
 * The handler **must** call the callback exactly once.
 */
export async function cacheProtocolHandler(
  params: RequestParameters,
  callback: RequestCallback
) {
  try {
    // 1️⃣ Strip the leading "tiles/" (or any other prefix you want)
    //    and split into z/x/y.
    const path = params.url; // e.g. "tiles/12/3456/7890"
    const parts = path.split('/');

    // Expect at least 4 parts: ["tiles", z, x, y]
    if (parts.length < 4) {
      throw new Error(`Invalid cache URL: ${params.url}`);
    }

    const [, zStr, xStr, yStr] = parts; // ignore the first segment ("tiles")
    const z = Number(zStr);
    const x = Number(xStr);
    const y = Number(yStr);

    if (Number.isNaN(z) || Number.isNaN(x) || Number.isNaN(y)) {
      throw new Error(`Invalid tile coordinates in ${params.url}`);
    }

    // 2️⃣ Look up the tile in IndexedDB
    const cache = await TileCache.get();
    const tileData = await cache.get(z, x, y);

    if (!tileData) {
      // Tile not cached → tell MapLibre to treat it as a 404.
      // The callback signature for an error is: callback(error)
      const err = new Error(`Tile not found in cache: ${params.url}`);
      // @ts-ignore – MapLibre expects an Error object as the first argument.
      callback(err);
      return;
    }

    // 3️⃣ Return the raw bytes.
    // MapLibre expects an ArrayBuffer (or Uint8Array) as the second argument.
    // The third argument is an optional "response" object where you can set
    // cache-control headers, MIME type, etc.
    callback(null, tileData.buffer, {
      // The MIME type for vector tiles is important for some browsers.
      // It also helps MapLibre decide how to decode the data.
      mimeType: 'application/x-protobuf',
    });
  } catch (e) {
    // Any unexpected error → forward it to MapLibre.
    // @ts-ignore
    callback(e as Error);
  }
}

/**
 * Helper to register the protocol on a MapLibre map instance.
 */
export function registerCacheProtocol(map: maplibregl.Map) {
  // The name you pass here (`'cache'`) becomes the scheme part of the URL.
  map.addProtocol('cache', cacheProtocolHandler);
}
```

> **Important notes**
> * The handler **must be synchronous** from MapLibre’s point of view – i.e. you *must* call `callback` exactly once, even if you do async work inside the function.  
> * `callback(null, arrayBuffer, {mimeType})` signals success.  
> * `callback(error)` signals a failure (MapLibre will treat it as a 404 and will try the next source in the style, if any).

