## 4️⃣  Putting it all together – a minimal app

```tsx
// src/App.tsx
import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { registerCacheProtocol } from './cache/cacheProtocol';
import { TileCache } from './cache/TileCache';

// ---------------------------------------------------------------------------
// 1️⃣  A tiny helper that pre‑populates the cache with a few tiles.
//     In a real app you would fill the cache on‑the‑fly (e.g. via a Service
//     Worker, a background sync, or a manual “download area” UI).
// ---------------------------------------------------------------------------
async function preloadDemoTiles() {
  const cache = await TileCache.get();

  // Example: fetch a tile from the public OSM vector tile service and store it.
  // (Replace with your own tile source if you prefer.)
  const demoUrl = (z: number, x: number, y: number) =>
    `https://tile.openstreetmap.org/${z}/${x}/${y}.png`; // <-- PNG just for demo

  // For vector tiles you would use a .pbf endpoint, e.g.
  //   `https://tileserver.example.com/data/v3/${z}/${x}/${y}.pbf`

  // We'll just fetch a few PNGs to prove the flow works.
  // In practice you *must* fetch a PBF and store the raw bytes.
  const tilesToCache = [
    { z: 0, x: 0, y: 0 },
    { z: 1, x: 0, y: 0 },
    { z: 1, x: 1, y: 0 },
    { z: 1, x: 0, y: 1 },
    { z: 1, x: 1, y: 1 },
  ];

  for (const { z, x, y } of tilesToCache) {
    const resp = await fetch(demoUrl(z, x, y));
    const blob = await resp.blob();
    const arrayBuffer = await blob.arrayBuffer();
    await cache.put(z, x, y, new Uint8Array(arrayBuffer));
    console.log(`🗂️ Cached tile ${z}/${x}/${y}`);
  }
}

// ---------------------------------------------------------------------------
// 2️⃣  The React component that creates the map and registers the protocol.
// ---------------------------------------------------------------------------
export default function App() {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);

  useEffect(() => {
    // 2a️⃣  Pre‑load some demo tiles (only needed for the demo)
    preloadDemoTiles().catch(console.error);

    // 2b️⃣  Initialise the MapLibre map
    if (!mapContainer.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: {
        version: 8,
        sources: {
          // The source points to the custom scheme.
          // The `tiles` array can contain *any* number of URLs – we only need one.
          demo: {
            type: 'raster', // <-- change to 'vector' for real vector tiles
            tiles: ['cache://tiles/{z}/{x}/{y}'],
            tileSize: 256,
          },
        },
        layers: [
          {
            id: 'demo',
            type: 'raster',
            source: 'demo',
          },
        ],
      },
      center: [0, 0],
      zoom: 0,
    });

    // 2c️⃣  Register the custom protocol *after* the map is created.
    registerCacheProtocol(map);

    mapRef.current = map;

    return () => {
      map.remove();
    };
  }, []);

  return (
    <div
      ref={mapContainer}
      style={{ width: '100vw', height: '100vh' }}
    />
  );
}
```

### What you see in the demo

* The map loads the raster tiles that we stored in IndexedDB under the `cache://` scheme.  
* If you open the DevTools → Application → IndexedDB you’ll see a database called **`maplibre-tile-cache`** with a `tiles` object store.  
* If you delete a tile from the store and refresh the page, the map will show a missing‑tile placeholder (the same behaviour you’d get from a 404 on a normal HTTP source).

