## 1️⃣  IndexedDB helper (tiny wrapper)

```ts
// src/idb.ts
export interface TileKey {
  z: number;
  x: number;
  y: number;
}

/**
 * Tiny wrapper around IndexedDB that stores raw tile blobs.
 * The object store key is a string "z/x/y".
 */
export class TileCacheDB {
  private static DB_NAME = "tile-cache";
  private static STORE_NAME = "tiles";
  private static DB_VERSION = 1;

  private db!: IDBDatabase;

  /** Open (or create) the DB – call once at app start */
  async open(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const request = indexedDB.open(TileCacheDB.DB_NAME, TileCacheDB.DB_VERSION);

      request.onupgradeneeded = () => {
        const db = request.result;
        // keyPath is a string like "14/5234/12673"
        db.createObjectStore(TileCacheDB.STORE_NAME);
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  /** Turn a TileKey into the store key */
  private static key({ z, x, y }: TileKey): string {
    return `${z}/${x}/${y}`;
  }

  /** Store a tile (ArrayBuffer) */
  async put(key: TileKey, data: ArrayBuffer): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCacheDB.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCacheDB.STORE_NAME);
      store.put(data, TileCacheDB.key(key));
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  /** Retrieve a tile – returns undefined if not cached */
  async get(key: TileKey): Promise<ArrayBuffer | undefined> {
    return new Promise<ArrayBuffer | undefined>((resolve, reject) => {
      const tx = this.db.transaction(TileCacheDB.STORE_NAME, "readonly");
      const store = tx.objectStore(TileCacheDB.STORE_NAME);
      const request = store.get(TileCacheDB.key(key));
      request.onsuccess = () => resolve(request.result as ArrayBuffer | undefined);
      request.onerror = () => reject(request.error);
    });
  }

  /** Optional: delete a tile */
  async delete(key: TileKey): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCacheDB.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCacheDB.STORE_NAME);
      store.delete(TileCacheDB.key(key));
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
}
```

