## 2️⃣  Register the `cache://` protocol with MapLibre

```ts
// src/map.ts
import maplibregl, { Map, RequestParameters } from "maplibre-gl";
import { TileCacheDB, TileKey } from "./idb";

/**
 * The protocol handler receives the URL *after* the scheme.
 * For `cache://tiles/14/5234/12673` the `params.url` argument will be
 *   "tiles/14/5234/12673"
 *
 * MapLibre expects the handler to return a Promise that resolves to:
 *   - an ArrayBuffer (raw tile data) OR
 *   - a Response object (e.g. new Response(arrayBuffer, { headers }))
 *
 * The handler receives an AbortSignal (via `params.signal`) that we forward
 * to any fetch we might do as a fallback.
 */
export function registerCacheProtocol(map: Map, db: TileCacheDB) {
  map.addProtocol("cache", async (params: RequestParameters) => {
    // --------------------------------------------------------------
    // 1️⃣  Parse the URL into z/x/y
    // --------------------------------------------------------------
    // Expected pattern: "tiles/{z}/{x}/{y}"
    const match = params.url.match(/^tiles\/(\d+)\/(\d+)\/(\d+)$/);
    if (!match) {
      console.warn(`cache protocol received unexpected URL: ${params.url}`);
      // Let MapLibre fall back to a normal HTTP request (or you could throw)
      return null;
    }

    const [, zStr, xStr, yStr] = match;
    const key: TileKey = {
      z: Number(zStr),
      x: Number(xStr),
      y: Number(yStr),
    };

    // --------------------------------------------------------------
    // 2️⃣  Try to read from IndexedDB
    // --------------------------------------------------------------
    const cached = await db.get(key);
    if (cached) {
      // Return the raw bytes – MapLibre will treat it as a tile.
      return cached;
    }

    // --------------------------------------------------------------
    // 3️⃣  Cache‑miss fallback: fetch from the network, store, then return.
    // --------------------------------------------------------------
    // You can point this at any public tile endpoint you like.
    const remoteUrl = `https://tiles.example.com/${key.z}/${key.x}/${key.y}.pbf`;

    try {
      const response = await fetch(remoteUrl, { signal: params.signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const arrayBuffer = await response.arrayBuffer();

      // Store for next time (fire‑and‑forget – we don't block the tile render)
      db.put(key, arrayBuffer).catch((e) =>
        console.error("Failed to cache tile", key, e)
      );

      // Return the freshly‑fetched data
      return arrayBuffer;
    } catch (err) {
      console.error("Failed to fetch tile from network", remoteUrl, err);
      // Propagate the error to MapLibre – it will render a missing‑tile placeholder.
      throw err;
    }
  });
}
```

### What the handler **must** return

| Return type | Meaning for MapLibre |
|-------------|----------------------|
| `ArrayBuffer` | Raw tile data (no extra headers). |
| `Response`    | Allows you to set MIME type, caching headers, etc. |
| `null` / `undefined` | MapLibre will try the next protocol (e.g. `http`). |
| `Promise.reject` | Tile is considered missing → red “X”. |

In the snippet above we return an `ArrayBuffer` both for cached and freshly‑fetched tiles.

