## 3️⃣  Putting it all together – a minimal app entry point

```ts
// src/index.ts
import "maplibre-gl/dist/maplibre-gl.css";
import { Map } from "maplibre-gl";
import { TileCacheDB } from "./idb";
import { registerCacheProtocol } from "./map";

async function main() {
  // 1️⃣  Open the IndexedDB cache (must finish before we register the protocol)
  const tileCache = new TileCacheDB();
  await tileCache.open();

  // 2️⃣  Create the MapLibre map
  const map = new Map({
    container: "map", // <div id="map"></div> in your HTML
    style: {
      version: 8,
      sources: {
        // The source uses our custom scheme.
        "my-vector": {
          type: "vector",
          // Note the scheme – MapLibre will invoke the protocol handler.
          url: "cache://tiles/{z}/{x}/{y}",
          // If you need a min/max zoom you can still set them here.
          minzoom: 0,
          maxzoom: 14,
        },
      },
      layers: [
        {
          id: "my-layer",
          type: "fill",
          source: "my-vector",
          "source-layer": "my_layer_name", // whatever the source provides
          paint: {
            "fill-color": "#88c0d0",
            "fill-opacity": 0.6,
          },
        },
      ],
    },
    center: [0, 0],
    zoom: 2,
  });

  // 3️⃣  Register the protocol *after* the map instance exists
  registerCacheProtocol(map, tileCache);

  // 4️⃣  Optional: pre‑populate the cache (e.g. for the initial viewport)
  //    This is just a demo – you could also let the fallback fetch do it.
  const prefetch = async () => {
    const zoom = 2;
    const bounds = map.getBounds(); // lng/lat bounds of the view
    const tiles = tilesForBounds(bounds, zoom); // helper defined below
    for (const { x, y } of tiles) {
      const key = { z: zoom, x, y };
      // Skip if already cached
      if (await tileCache.get(key)) continue;
      const remote = `https://tiles.example.com/${zoom}/${x}/${y}.pbf`;
      try {
        const resp = await fetch(remote);
        if (!resp.ok) continue;
        const buf = await resp.arrayBuffer();
        await tileCache.put(key, buf);
      } catch (e) {
        console.warn("prefetch failed", remote, e);
      }
    }
  };
  map.once("load", prefetch);
}

/**
 * Helper: given a lng/lat bounds and a zoom, return the set of XYZ tiles
 * that intersect the bounds.  (Uses the standard WebMercator tile math.)
 */
function tilesForBounds(
  bounds: maplibregl.LngLatBounds,
  zoom: number
): { x: number; y: number }[] {
  const n = 1 << zoom;
  const lng2x = (lng: number) => Math.floor(((lng + 180) / 360) * n);
  const lat2y = (lat: number) => {
    const rad = (lat * Math.PI) / 180;
    const y = Math.floor(
      ((1 - Math.log(Math.tan(rad) + 1 / Math.cos(rad)) / Math.PI) / 2) * n
    );
    return Math.min(Math.max(y, 0), n - 1);
  };

  const x0 = lng2x(bounds.getWest());
  const x1 = lng2x(bounds.getEast());
  const y0 = lat2y(bounds.getNorth());
  const y1 = lat2y(bounds.getSouth());

  const tiles = [];
  for (let x = x0; x <= x1; x++) {
    for (let y = y0; y <= y1; y++) {
      tiles.push({ x, y });
    }
  }
  return tiles;
}

// Kick‑off
main().catch((e) => console.error("App init failed", e));
```

